/* @lc app=leetcode id=2049 lang=kotlin */ class Solution { fun countHighestScoreNodes(parents: IntArray): Int = parents.size.let { n -> parents.indices.groupBy { parents[it] }.let { g -> generateSequence(listOf(0)) { f -> f.flatMap { g[it].orEmpty() }.takeIf { it.isNotEmpty() } }.flatten().toList().let { order -> IntArray(n) { 1 }.also { sz -> order.reversed().forEach { v -> if (v > 0) sz[parents[v]] += sz[v] } }.let { sz -> order.map { v -> g[v].orEmpty().fold(1L) { a, c -> a * sz[c] } * maxOf(1, n - sz[v]) }.let { sc -> sc.max().let { m -> sc.count { it == m } } } } } } } }